#!/bin/zsh
# 小編萬聖夜美術：GPT 生圖（一張一張跑，tools/gen.sh 靠「最新的檔」抓圖，不能並行）
# 用法：zsh tools/prompts.sh [名稱...]（不給就全跑）；原圖存 work/gen/，轉檔用 tools/convert.sh
cd "$(dirname $0)/.."
G=tools/gen.sh
PAINT="hand-painted gouache illustration for a cozy mobile game, muted colors, soft paper grain, gentle flat lighting"
ROOM="Wide 3:2 image. A cut-away dollhouse cross-section of one room inside an old small Taiwanese elementary school on a mountaintop, at night on Halloween, seen perfectly straight on from the front like a theatre stage, no side walls and no ceiling visible: we only see the back wall and a thin strip of floor along the bottom 10 percent. Dim blue-green moonlight with a few warm orange glows from small kid-made jack-o'-lantern decorations, paper bats and cotton cobwebs made by children. The lower middle of the room where characters walk is open and empty, all furniture stands against the back wall"
NOPPL="no people, no characters, no monsters, no animals, no text, no letters, no numbers, no logos"
SPR="children's picture-book gouache style with a clean dark brown outline, flat side view facing right, full body, one single creature centered with empty space around it, plain solid flat magenta #FF00FF background, no shadow, no ground, no text, square image"
typeset -A P
P[room-class]="$ROOM. A classroom: a dark green chalkboard on the back wall with faint chalk pumpkin doodles, wooden pupil desks and chairs pushed against the wall, tall windows showing dark mountains and a full moon. $PAINT, $NOPPL"
P[room-lab]="$ROOM. A science classroom: tall wooden shelves with glass beakers, jars and potted plants, a small sink, a plastic anatomy skeleton model standing in the corner wearing a party hat, a periodic-style poster with no writing. $PAINT, $NOPPL"
P[room-library]="$ROOM. A small school library: tall wooden bookshelves full of colorful books along the back wall, a reading corner with cushions, a globe on a shelf, string lights. $PAINT, $NOPPL"
P[room-nurse]="$ROOM. The school nurse room: a white bed with a pale green curtain on a rail, a white medicine cabinet, a height scale, a folding screen, a first aid box. $PAINT, $NOPPL"
P[room-music]="$ROOM. A music classroom: an upright piano, a drum set, xylophones on a low shelf, music stands, blank posters of musical notes shapes. $PAINT, $NOPPL"
P[room-gym]="$ROOM. A small school assembly hall used as a gym: a basketball backboard and hoop high on the back wall, a low wooden stage with a red curtain at one side, folded chairs stacked, hanging orange paper lanterns. $PAINT, $NOPPL"
P[room-office]="$ROOM. The principal's office: a big wooden desk with a desk lamp, a glass cabinet full of golden trophies, framed certificate shapes with no writing, a potted orchid, a sofa. $PAINT, $NOPPL"
P[room-hall]="$ROOM. An open school corridor: a long row of small white tiled hand-washing sinks with taps along the back wall, a cork bulletin board with children's pumpkin drawings, a drinking fountain, terrazzo floor. $PAINT, $NOPPL"
P[room-roof]="$ROOM. The flat rooftop of the school building at night: a low green railing along the back, a round water tower on a stand, potted plants, a big full moon over dark mountain ridges and a sea of clouds, stars. $PAINT, $NOPPL"
P[sky]="Vertical 2:3 background. Night sky over green mountains in Taiwan on Halloween: a big pale full moon upper right, deep blue sky with soft stars, layers of dark blue-green mountain ridges at the bottom with a sea of clouds lit by moonlight. The center is calm and empty. $PAINT, $NOPPL"
P[m-pumpkin]="A small cute-creepy walking jack-o'-lantern monster with short stubby legs and tiny arms raised, carved grin and eyes glowing warm orange from inside, a curly green vine on top. $SPR"
P[m-ghost]="A small white bedsheet ghost floating, two round black eye holes and a little open mouth, wavy hem with no legs, arms like little sheet bumps reaching forward. $SPR"
P[m-bat]="A small round purple-black bat flying with both wings spread wide, big pointy ears, tiny white fangs, glowing red eyes. $SPR"
P[m-mummy]="A short chubby mummy wrapped in white toilet paper rolls with a few loose strips, one glowing yellow eye peeking out, both arms stretched forward, walking. $SPR"
P[m-boss]="A huge round jack-o'-lantern king monster with a crooked golden paper crown, thick vine arms with leafy hands, short legs, a big mean carved grin glowing fiery orange. $SPR"
P[items]="A 4 by 4 grid of 16 separate game item icons on a plain solid flat magenta #FF00FF background, every icon well separated with wide magenta gaps, all the same size, children's picture-book gouache sticker style with a clean dark brown outline, no shadows. In reading order: 1 a glowing jack-o'-lantern, 2 an orange plastic pumpkin candy bucket, 3 a silver microphone, 4 a black witch hat, 5 a string of orange and black paper bat bunting, 6 a brass school hand bell, 7 a folded black and purple cape, 8 a vintage camera, 9 a red cassette boombox, 10 a giant swirl lollipop, 11 a glass cookie jar full of cookies, 12 a coil of warm fairy lights, 13 a rolled up party banner, 14 a pink and white bunny ears headband, 15 a golden school trophy cup, 16 a wooden treasure chest carved like a pumpkin. No text, no letters, no numbers"
P[skills]="A 4 by 4 grid of 16 separate game skill icons on a plain solid flat magenta #FF00FF background, every icon well separated with wide magenta gaps, all the same size, children's picture-book gouache sticker style with a clean dark brown outline, no shadows, things from a Taiwanese elementary school. In reading order: 1 a stick of white chalk with a little chalk dust, 2 a coiled jump rope with two wooden handles, 3 a red rubber dodgeball, 4 a silver PE coach whistle on a red cord, 5 a traditional Taiwanese bamboo broom, 6 a red and yellow Chinese diabolo spinning top with two sticks and string, 7 a folded white paper airplane, 8 a blue mop standing in a water bucket, 9 a small green desk fan, 10 a red elementary school backpack, 11 a pair of white school indoor slip-on shoes, 12 a steel school lunch tray with rice and dishes, 13 a red reward stamp with a star, 14 a brass school bell, 15 a candy corn, 16 a red heart. No text, no letters, no numbers"
P[skills2]="A 4 by 4 grid of 16 separate game skill icons on a plain solid flat magenta #FF00FF background, every icon well separated with wide magenta gaps, all the same size, children's picture-book gouache sticker style with a clean dark brown outline, no shadows, things from a Taiwanese elementary school. In reading order: 1 an orange basketball, 2 a light brown plastic school soprano recorder flute, 3 a small pile of shiny thumbtacks, 4 a felt chalkboard eraser puffing white chalk dust, 5 a colorful striped hula hoop, 6 a feathered shuttlecock toy, 7 a small desk globe, 8 a yellow pencil, 9 a wooden ruler, 10 a pink rubber eraser, 11 a box of crayons, 12 a watercolor paint brush, 13 a yellow school cap, 14 a red megaphone, 15 a triangle ruler, 16 a school name tag. No text, no letters, no numbers"
P[m-ghostboss]="A huge white bedsheet ghost boss with a tattered torn hem, two big glowing purple eyes and a wide wavy mouth, long sleeve-like arms spread wide, an old janitor's cap on its head, a faint purple glow around it, floating. $SPR"
P[logo]="Chalk lettering on a pure flat black background: the five Traditional Chinese characters 小編萬聖夜 written large and bold in thick chalk, the first two characters in white chalk and the last three in orange chalk, playful hand-lettered schoolteacher style, slightly uneven strokes with chalk dust texture and rough edges, one line, centered, a tiny chalk bat and a tiny chalk pumpkin doodle beside the words, nothing else, wide 3:2 image"
if (( $# )); then names=($@); else names=(room-class m-pumpkin room-hall room-lab items skills m-ghost m-bat m-mummy m-boss room-library room-nurse room-music room-gym room-office room-roof sky logo); fi
for n in $names; do
  [ -f work/gen/$n.png ] && { echo "skip $n"; continue; }
  zsh $G work/gen/$n.png "${P[$n]}"
done
